import { durationFromMs, type Duration } from "@bufbuild/protobuf/wkt";

/** True when a value looks like a protobuf Duration message or init. */
export function isDurationValue(value: unknown): value is Duration {
  return (
    typeof value === "object" &&
    value !== null &&
    ("seconds" in value || "nanos" in value) &&
    !Array.isArray(value)
  );
}

/** Public millisecond field name → protobuf Duration field name. */
const durationPublicToWire = {
  timeoutMs: "timeout",
  queueTimeoutMs: "queueTimeout",
  maximumLifetimeMs: "maximumLifetime",
  afterMs: "after",
} as const;

type DurationPublicName = keyof typeof durationPublicToWire;
type DurationWireName = (typeof durationPublicToWire)[DurationPublicName];

type WireToPublic = {
  [K in DurationWireName]: {
    [P in DurationPublicName]: (typeof durationPublicToWire)[P] extends K
      ? P
      : never;
  }[DurationPublicName];
};

/**
 * Recursively rename known protobuf Duration fields to `*Ms` numbers for
 * public request construction. Field-name based so maps like `labels` are
 * left alone.
 */
export type DurationFieldsToMs<T> = T extends readonly (infer U)[]
  ? DurationFieldsToMs<U>[]
  : T extends object
    ? {
        [K in keyof T as K extends DurationWireName
          ? WireToPublic[K]
          : K]: K extends DurationWireName
          ? undefined extends T[K]
            ? number | undefined
            : number
          : DurationFieldsToMs<T[K]>;
      }
    : T;

/** Convert public `*Ms` numbers on known duration fields into protobuf Durations. */
export function materializeDurationFields<T>(value: T): T {
  return materializeDurationFieldsAt(value) as T;
}

function materializeDurationFieldsAt(value: unknown): unknown {
  if (value === null || value === undefined) return value;
  if (typeof value !== "object") return value;
  if (isDurationValue(value)) return value;
  if (Array.isArray(value)) {
    return value.map((item) => materializeDurationFieldsAt(item));
  }
  const out: Record<string, unknown> = {};
  for (const [key, child] of Object.entries(value as Record<string, unknown>)) {
    if (key in durationPublicToWire && typeof child === "number") {
      const wireKey =
        durationPublicToWire[key as DurationPublicName];
      out[wireKey] = durationFromMs(child);
      continue;
    }
    out[key] = materializeDurationFieldsAt(child);
  }
  return out;
}

