async #update(
  operation: string,
  method:
    | ((
        id: string,
        request:
          | StartOptions
          | StopOptions
          | PauseOptions
          | ArchiveOptions
          | DeleteOptions,
        options: OperationOptions,
      ) => Promise<SandboxInfo>)
    | undefined,
  request:
    | StartOptionsInput
    | StopOptionsInput
    | PauseOptionsInput
    | ArchiveOptionsInput
    | DeleteOptionsInput,
  options: OperationOptions,
): Promise<SandboxInfo> {
  const wire = materializeDurationFields(request) as
    | StartOptions
    | StopOptions
    | PauseOptions
    | ArchiveOptions
    | DeleteOptions;
  return this.#serialized(
    operation,
    options,
    optionalTimeoutMs(wire.timeout) ?? this.#timeoutMs,
    async (signal) => {
      if (!method) unsupported(this.providerName, operation);
      const info = await awaitWithSignal(
        () =>
          method.call(
            this.#backend,
            this.id,
            clone(wire),
            operationOptions(options, signal),
          ),
        signal,
      );
      this.#info = clone({ ...info, provider: this.providerName });
      return this.info();
    },
  );
}

