// Daytona provider construction and native SDK orchestration are handwritten.

import type {
  Backend,
  ConfigWire,
  CreateOptionsWire,
  CreateResult,
  OperationOptions,
  Provider,
} from "@sandbox-kit/sandbox/wire";

export abstract class ProviderBase implements Provider {
  abstract readonly name: string;
  abstract initialize(config: ConfigWire): Backend;
}

export abstract class BackendBase implements Backend {
  abstract readonly name: string;
  abstract create(
    request: CreateOptionsWire,
    options: OperationOptions,
  ): Promise<CreateResult>;
  abstract close(options: OperationOptions): Promise<void>;
}

// Modal provider construction and native SDK orchestration are handwritten.

import type {
  Backend,
  ConfigWire,
